source('scripts/load.R')
cfg<-jsonlite::read_json('config/study.json',simplifyVector=TRUE)
out<-run_simulations(cfg)
saveRDS(out,'results/simulation.rds');csv(out$performance,'results/replicate_metrics.csv')
csv(out$example$metadata,'data/synthetic_isolates.csv')
csv(out$example$distance,'data/true_snp_distances.csv')
summary<-do.call(rbind,lapply(c('precision','sensitivity_all','sensitivity_sampled','false_positive_rate'),function(metric){z<-mc(out$performance,c('scenario','threshold','method'),metric);z$metric<-metric;z}))
csv(summary,'results/performance_summary.csv')
analyse_example(out$example,cfg)
make_figures(out,summary,cfg)
jsonlite::write_json(list(seed=cfg$seed,replicates=cfg$replicates,scenarios=cfg$scenarios,isolates_per_population=cfg$isolates,distinct_populations=cfg$replicates,paired_scenarios=TRUE,total_scenario_evaluations=cfg$replicates*length(cfg$scenarios),data_type='fully synthetic',local_runtime='Windows R on Toshiba; sequencing runtime recorded separately in results/wgs',source_hashes=lapply(setNames(list.files('R',full.names=TRUE),list.files('R')),function(f)digest::digest(file=f,algo='sha256'))),'provenance/simulation_run.json',pretty=TRUE,auto_unbox=TRUE)
versions<-data.frame(package=c('R','ggplot2','ape','jsonlite','digest'),version=c(as.character(getRversion()),vapply(c('ggplot2','ape','jsonlite','digest'),function(p)as.character(packageVersion(p)),character(1))))
csv(versions,'provenance/R_versions.csv')
cat('Completed',nrow(out$performance),'paired scenario/threshold/method evaluations.\n')
